mapper.delete:
DELETE
  FROM icam10_fee
 WHERE icam10_company_id = #{companyId}
   AND icam10_fee_type   IN ('20407','24926')  /* (20407:미지급사무관리보수 / 24926:현금미지급사무보수) */
   AND icam10_std_date BETWEEN #{startDate} AND #{closeDate}

DELETE
  FROM icam10_fee
 WHERE icam10_company_id = #{companyId}
   AND icam10_fee_type   IN ('20402','24923')  /* (20402:미지급운용보수 / 24923:현금미지급운용보수) */
   AND icam10_std_date BETWEEN #{startDate} AND #{closeDate}
   AND icam10_fund_cd  LIKE #{fundCode}

DELETE
  FROM icam12_fee_book
 WHERE icam12_company_id = #{companyId}
   AND icam12_std_date BETWEEN #{startDate} AND #{closeDate}

