     , #{p.icamCompanyCode}
     , #{p.icamCompanyName}
     , #{p.feeType}
     , #{p.rmkCode}
     , #{p.rmkName}
     , #{p.drcrType}
     , #{p.fundCode}
     , #{p.fundName}
     , #{p.fee}
