     , #{p.fxRate}
     , #{p.afPayDate}
     , #{p.bfPayDate}
     , #{p.consignmentCode}
     , #{p.consignmentName}
     , f_sysdate()
     , #{p.worker}

INSERT
  INTO icam12_fee_book
