     , #{p.companyId}
     , #{p.icamCompanyCode}
     , #{p.icamCompanyName}
     , #{p.stdDate}
     , #{p.fundCode}
     , #{p.fundName}
     , #{p.curCode}
     , #{p.forFee}
     , #{p.fee}
     , #{p.consignmentCode}
     , #{p.consignmentName}
     , null
     , f_sysdate()
     , #{p.worker}

mapper.select:
SELECT COUNT(*)
  FROM ( SELECT *
           FROM icam11_fee_deposit
          WHERE icam11_company_id      = #{companyId}
            AND icam11_icam_company_cd = #{icamCompanyCode}
            AND icam11_fund_cd         = #{fundCode}
            AND icam11_start_date <= #{stdDate}
          ORDER BY icam11_start_date DESC
          LIMIT 1 ) t

