SELECT COUNT(*)
  FROM sys15_corp
 WHERE sys15_company_id = #{companyId}
   AND sys15_corp_cd = #{corpCode}
   AND sys15_corp_id != #{corpId}
   AND sys15_use_yn = 'true'

